String fn0(List<int> counts) {
  int mask = 0;
  for (int count in counts) {
    int bin = count & 1;
    mask = (mask << 1) | bin;
  }
  return mask.toRadixString(2);
}

List<int> fn0(List<Object> ingredients, double multiplier) {
  List<int> result = [];
  for (var item in ingredients) {
    if (item is int) {
      result.add((item * multiplier).round());
    } else {
      var subInfo = item as List<Object>;
      double subMult = subInfo[0] as double;
      List<Object> subRec = subInfo[1] as List<Object>;
      result.addAll(fn0(subRec, multiplier * subMult));
    }
  }
  return result;
}

