String fn0(List<int> arrivalHours) {
  if (arrivalHours.length < 2) return "Insufficient data";

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    return a;
  }

  int g = 0;
  for (int i = 1; i < arrivalHours.length; i++) {
    g = gcd(g, (arrivalHours[i] - arrivalHours[i - 1]).abs());
  }

  return "Optimal interval: ${g}h";
}

