}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {





  TreeNode root = TreeNode(
    'A',
    [TreeNode('B', [TreeNode('D'), TreeNode('E')]), TreeNode('C', [TreeNode('F'), TreeNode('G')])],
  );

  List<String> bfs(TreeNode node) {
    List<String> result = [];
    if (node == null) return result;

    List<TreeNode> queue = [];
    queue.add(node);
    result.add(node.value);

    while (queue.isNotEmpty) {
      TreeNode current = queue.removeAt(0);

      for (TreeNode child in current.children) {
        queue.add(child);
        result.add(child.value);
      }
    }

    return result;
  }

  List<String> bfsResult = bfs(root);
  print('BFS traversal order: ${bfsResult.join(', ')}');
}

