  List<int> prices = [1, 5, 8, 9, 10, 17, 17, 20, 24, 30];
  int n = prices.length;

  List<int> dp = List<int>.filled(n + 1, 0);

  for (int i = 0; i <= n; i++) {
    for (int len = 1; len <= i; len++) {
      int currentMax = -1;
      for (int j = 0; j <= i - len; j++) {
        currentMax = currentMax > prices[j]
