void fn0() {

  List<int> nums = [10, 9, 2, 5, 3, 7, 101, 18];

  int longestIncreasingSubsequence(List<int> nums) {
    if (nums.isEmpty) return 0;

    List<int> tails = List<int>.filled(nums.length, 1);

    for (int i = 1; i < nums.length; i++) {
      for (int j = 0; j < i; j++) {
        if (nums[i] > nums[j]) {
          tails[i] = tails[i] > tails[j] + 1 ? tails[i] : tails[j] + 1;
        }
      }
    }

    return tails.reduce((a, b) => a > b ? a : b);
  }

  int lisLength = longestIncreasingSubsequence(nums);
  print('Length of Longest Increasing Subsequence: $lisLength');
}

