void fn0(List<String> args) {

  if (args.length != 2) {
    print('Usage: dart run <script.dart> <pattern> <text>');
    return;
  }

  final String pattern = args[0];
  final String text = args[1];

  bool hasMatch(String pattern, String text) {
    int m = pattern.length;
    int n = text.length;
    List<List<bool>> dp = List.generate(m + 1, (_) => List.filled(n + 1, false));

    for (int i = 0; i <= m; i++) dp[i][0] = true;
    for (int j = 1; j <= n; j++) dp[0][j] = true;

    for (int i = 1; i <= m; i++) {
      for (int j = 1; j <= n; j++) {
        bool include = dp[i - 1][j];
        bool exclude = dp[i][j - 1];

        if (pattern[i - 1] == text[j - 1]) {
          include = true;
        }

        dp[i][j] = include || exclude;
      }
    }

    return dp[m][n];
  }

  final bool isMatch = hasMatch(pattern, text);
  print('Pattern: "$pattern"');
  print('Text:    "$text"');
  print(isMatch ? 'Match' : 'No Match');
}

