import 'dart:async';
import 'dart:convert';
class TreeNode {
  int value;
  TreeNode? left;
  TreeNode? right;

  TreeNode(this.value, {this.left, this.right});
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  TreeNode root = TreeNode(
    1,
    left: TreeNode(
      2,
      left: TreeNode(4),
      right: TreeNode(5),
    ),
    right: TreeNode(3),
  );

  void inorder(TreeNode? node, List<int> result) {
    if (node == null) return;
    inorder(node.left, result);
    result.add(node.value);
    inorder(node.right, result);
  }

  void preorder(TreeNode? node, List<int> result) {
    if (node == null) return;
    result.add(node.value);
    preorder(node.left, result);
    preorder(node.right, result);
  }

  void postorder(TreeNode? node, List<int> result) {
    if (node == null) return;
    postorder(node.left, result);
    postorder(node.right, result);
    result.add(node.value);
  }

  List<int> inorderResult = [];
  inorder(root, inorderResult);
  print('Inorder traversal: ${inorderResult.join(' ')}');

  List<int> preorderResult = [];
  preorder(root, preorderResult);
  print('Preorder traversal: ${preorderResult.join(' ')}');

  List<int> postorderResult = [];
  postorder(root, postorderResult);
  print('Postorder traversal: ${postorderResult.join(' ')}');
}

