@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final data = [
    [1, 2],
    [2, 4],
    [3, 6],
    [4, 8],
    [5, 10],
  ];

  int n = data.length;

  double sumX = 0;
  double sumY = 0;
  double sumXY = 0;
  double sumX2 = 0;

  for (var point in data) {
    final x = point[0];
    final y = point[1];

    sumX += x;
    sumY += y;
    sumXY += x * y;
    sumX2 += x * x;
  }

  double m = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
  double b = (sumY - m * sumX) / n;

  print('Linear Regression Results:');
  print('Slope (m): $m');
  print('Intercept (b): $b');
  print('Equation: y = ${m.toStringAsFixed(2)}x + ${b.toStringAsFixed(2)}');

  final prediction = m * 6 + b;
  print('Prediction for x=6: $prediction');
}

