@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> fn0(List<List<int>> moistureGrid) {
  List<int> stack = [];
  int maxDepth = 0;
  int balancedZones = 0;
  int remaining = 0;
  for (int r = 0; r < moistureGrid.length; r++) {
    for (int c = 0; c < moistureGrid[r].length; c++) {
      if (stack.isNotEmpty && stack.last == moistureGrid[r][c]) {
        stack.removeLast();
        balancedZones++;
      } else {
        stack.add(moistureGrid[r][c]);
        if (stack.length > maxDepth) maxDepth = stack.length;
      }
    }
  }
  for (int m in stack) {
    if (m != 0) remaining++;
  }
  return {'maxDepth': maxDepth, 'balancedZones': balancedZones, 'remaining': remaining};
}

import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {
  if (args.length != 2) {
    print('Usage: dart run <script.dart> <string1> <string2>');
    print('Computes the Levenshtein (edit) distance between the two strings.');
    return;
  }

  String str1 = args[0];
  String str2 = args[1];

  int m = str1.length;
  int n = str2.length;

  List<List<int>> dp = List.generate(m + 1, (_) => List.filled(n + 1, 0));

  for (int i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (int j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      int cost = str1[i - 1] == str2[j - 1] ? 0 : 1;
      dp[i][j] = [dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost].reduce((a, b) => a < b ? a : b);
    }
  }

  print('Levenshtein distance between "$str1" and "$str2": ${dp[m][n]}');
}

