void fn0(List<String> args) {
  if (args.length != 2) {
    print('Usage: dart run <script.dart> <int1> <int2>');
    return;
  }

  final aInput = int.tryParse(args[0]);
  final bInput = int.tryParse(args[1]);

  if (aInput == null || bInput == null) {
    print('Error: both arguments must be valid integers.');
    return;
  }

  int a = aInput;
  int b = bInput;

  while (b != 0) {
    final temp = b;
    b = a % b;
    a = temp;
  }

  print('GCD: $a');
}
